function tokyoDetailExtras(p){
 const photo=tokyoPhotos[p.id],guide=tokyoVisitGuides[p.id];if(!photo||!guide)return '';
 return `<figure class="detailPhoto"><img src="${photo.src}" alt="${photo.alt}" width="1000" height="650"><figcaption><a href="${photo.source}" target="_blank" rel="noopener">사진 출처 · ${photo.source.includes('commons.wikimedia.org')?'Wikimedia Commons':p.pref==='도쿄'?'GO TOKYO':'공식 관광 안내'}</a></figcaption></figure><dl class="visitFacts"><div><dt>찾아가는 방법</dt><dd>${guide.access}</dd></div><div><dt>추천 관람 시간</dt><dd>${guide.duration}</dd></div></dl><p class="visitEstimate">관람 시간은 일정 구성을 위한 제안입니다. 대기·식사·교통 시간은 별도입니다.</p>`;
}
